/**
 * Tender websites from the "Master Classification - Direct Website Links" sheet, one per web address.
 * NIC: an NIC GePNIC portal; every organisation's open tenders are listed without a CAPTCHA.
 * PAGE: a company page that lists its tenders as plain HTML. MANUAL: no public list a program can read (login,
 * CAPTCHA, a script-built page, or a home page without tenders), so it is kept here as a link to check by hand.
 */
export type SiteMethod = "NIC" | "PAGE" | "MANUAL";
/**
 * note: for a MANUAL site, why it is not read, as "KIND:text". COVERED:<host> means its tenders are already on a portal
 * that is searched; LOGIN, CAPTCHA, SCRIPT, DOWN and NO_LIST say what stopped a program (checked 17 Nov 2026).
 */
export type SiteSeed = { host: string; name: string; url: string; category: string; method: SiteMethod; note?: string };

